import os
from typing import Any, Dict, Optional

from openai import OpenAI


class ManagedModelResolver:
    def __init__(
        self,
        api_key: Optional[str] = None,
        base_url: Optional[str] = None,
        default_model: str = "gpt-4o-mini",
    ) -> None:
        self.client = OpenAI(
            api_key=api_key or os.environ.get("OPENAI_API_KEY"),
            base_url=base_url or os.environ.get("OPENAI_BASE_URL"),
        )
        self.default_model = default_model

    def resolve_model(self, requested: Optional[str] = None) -> str:
        target = requested or self.default_model
        page = self.client.models.list()
        available = {m.id for m in page.data}

        if target in available:
            return target

        aliases = {
            "fast": "gpt-4o-mini",
            "balanced": "gpt-4o-mini",
            "reasoning": "gpt-4.1",
            "vision": "gpt-4o-mini",
        }

        aliased = aliases.get(target)
        if aliased and aliased in available:
            return aliased

        for candidate in (self.default_model, "gpt-4o-mini", "gpt-4.1"):
            if candidate in available:
                return candidate

        raise RuntimeError("No suitable OpenAI model available for invocation")

    def invoke(
        self,
        prompt: str,
        requested_model: Optional[str] = None,
        temperature: float = 0.2,
    ) -> Dict[str, Any]:
        model = self.resolve_model(requested_model)
        response = self.client.responses.create(
            model=model,
            temperature=temperature,
            input=prompt,
        )

        text = getattr(response, "output_text", None)
        if not text:
            parts = []
            for item in getattr(response, "output", []) or []:
                for content in getattr(item, "content", []) or []:
                    if getattr(content, "type", None) == "output_text":
                        parts.append(getattr(content, "text", ""))
            text = "".join(parts)

        return {
            "provider": "openai",
            "resolved_model": model,
            "response_id": getattr(response, "id", None),
            "text": text,
        }
